$table=function(array $rows,array $columns){if(!$rows){echo '<div class="empty">No records yet. New activity will appear here.</div>';return;}echo '<div class="table-wrap"><table><thead><tr>';foreach($columns as $label)echo '<th>'.esc($label).'</th>';echo '</tr></thead><tbody>';foreach($rows as $r){echo '<tr>';foreach($columns as $key=>$label){$value=$r[$key]??'—';if($key==='region')$value=\App\Libraries\GeographyCatalog::label((string)$value);echo '<td>';if(in_array($key,['state','stage','source','verification','subscription'],true))echo '<span class="badge '.esc((string)$value,'attr').'">'.esc(str_replace('_',' ',(string)$value)).'</span>';else echo esc(is_scalar($value)?(string)$value:'');echo '</td>';}echo '</tr>';}echo '</tbody></table></div>';};
