<?php if($personal && $page==='shift_requests'): ?><section class="card"><h2>Review shift replacements</h2><p class="notice">Approval cancels every prior shift listed for that request and schedules the proposed visit. The affected agencies receive a coverage notice. Declining leaves your schedule unchanged.</p><?php foreach($shift_requests as $r): ?><article><h3><?= esc($r['agency_name'].' · '.$r['state']) ?></h3><p>Proposed: <?= esc(str_replace('T',' ',$r['starts_at']).' to '.str_replace('T',' ',$r['ends_at']).' '.$r['timezone'].' · '.$r['service']) ?></p><p>Expires: <?= esc($r['expires_at']) ?> UTC</p><h4>Prior shifts to cancel</h4><?php $table($r['replaced_shifts'],['agency_name'=>'Agency','starts_at'=>'Start UTC','ends_at'=>'End UTC','state'=>'Current state']) ?><?php if($r['state']==='pending'):$form('shift_decision',['decision'=>['Decision','select',['decline'=>'Decline and keep my current shifts','approve'=>'Approve replacement and cancel listed shifts']],'?password'=>['Account password required for approval','password'],'?confirm'=>['I approve cancellation of every listed prior shift and understand the agencies must arrange coverage.','checkbox']],$refs($r),'Save my decision');endif ?></article><?php endforeach;if(!$shift_requests): ?><p class="empty">No shift replacement requests.</p><?php endif ?></section><?php endif ?>
