<?php foreach($visits as $v): ?><article class="card"><span class="badge <?= esc($v['state'],'attr') ?>"><?= esc($v['state']) ?></span><h2><?= esc($v['client_name']) ?> · <?= esc($v['service']) ?></h2><p><?= esc($v['caregiver_name'].' · '.$v['location']) ?></p><p><?= esc($v['starts_at'].' – '.$v['ends_at']) ?> UTC</p><?php if(in_array($page,['care','today'],true)): ?><p><?= nl2br(esc($v['instructions'])) ?></p><?php endif ?>
